Given the root of a binary tree, Find its inorder traversal using Morris Traversal, i.e., without using recursion or a stack.Examples:Input:Output: [4, 2, 5, 1, 3]Explanation: Inorder traversal (Left->Root->Right) of the tree is 4, 2, 5, 1, 3.Input:Output: [1, 7, 10, 8, 6, 10, 5, 6]Explanation: Inorder traversal (Left->Root->Right) of the tree is 1, 7, 10, 8, 6, 10, 5, 6.Try It YourselfApproach:We want to traverse the tree and come back to the root after finishing the left subtree, but without a stack. Morris Traversal achieves this by temporarily modifying the tree:For each node, check if it has a left child.If it does not have a left child, visit it and move to the right child.If it has a left child, find the inorder predecessor (rightmost node in the left subtree).Make the current node as the right child of its inorder predecessor (temporary link).Move to the left child.When you encounter a temporary link again, it means the left subtree is fully visited:Remove the temporary link.Visit the current node.Move to the right child.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

vector<int> inOrder(Node* root) {
    vector<int> res;
    Node* curr = root;

    while (curr != nullptr) {
        if (curr->left == nullptr) {

            // If no left child, visit this node 
            // and go right
            res.push_back(curr->data);
            curr = curr->right;
        }
        else {

            // Find the inorder predecessor of curr
            Node* prev = curr->left;
            while (prev->right != nullptr &&
                                 prev->right != curr) {
                prev = prev->right;
            }

            // Make curr the right child of its 
            // inorder predecessor
            if (prev->right == nullptr) {
                prev->right = curr;
                curr = curr->left;
            } 
            else {

                // Revert the changes made in 
                // the tree structure
                prev->right = nullptr;
                res.push_back(curr->data);
                curr = curr->right;
            }
        }
    }
    return res;
}


int main() {

    // Representation of input binary tree:
    //           1
    //          / \
    //         2   3
    //        / \  
    //       4   5
    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    vector<int> res = inOrder(root);

     for (int data : res) {
        cout << data << " ";
    }

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100000

// Node Structure
struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

int* inOrder(struct Node* root, int* size) {
    struct Node* curr = root;
    int capacity = MAX_SIZE;      
    int* res = (int*)malloc(capacity * sizeof(int));
    int count = 0;

    while (curr != NULL) {
        if (curr->left == NULL) {

            // If no left child, visit this node 
            // and go right
            if (count >= capacity) {
                capacity *= 2;
                res = (int*)realloc(res, capacity * sizeof(int));
            }
            res[count++] = curr->data;
            curr = curr->right;
        }
        else {

            // Find the inorder predecessor of curr
            struct Node* prev = curr->left;
            while (prev->right != NULL && prev->right != curr) {
                prev = prev->right;
            }

            // Make curr the right child of its 
            // inorder predecessor
            if (prev->right == NULL) {
                prev->right = curr;
                curr = curr->left;
            } 
            else {

                // Revert the changes made in 
                // the tree structure
                prev->right = NULL;
                if (count >= capacity) {
                    capacity *= 2;
                    res = (int*)realloc(res, capacity * sizeof(int));
                }
                res[count++] = curr->data;
                curr = curr->right;
            }
        }
    }

    // set the size
    *size = count;  
    return res;
}

// Helper to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

int main() {

    // Binary tree:
    //           1
    //          / \
    //         2   3
    //        / \  
    //       4   5
    struct Node* root = createNode(1);
    root->left = createNode(2);
    root->right = createNode(3);
    root->left->left = createNode(4);
    root->left->right = createNode(5);

    int size;
    int* res = inOrder(root, &size);

    for (int i = 0; i < size; i++) {
        printf("%d ", res[i]);
    }

    free(res);
    return 0;
}


